<?php
require_once __DIR__.'/../includes/bootstrap.php';
$active='deliveries';
$filter=strtolower(trim((string)($_GET['status']??'all')));
if(!in_array($filter,['all','delivered','pending','no-bidder'],true))$filter='all';
db_statement("UPDATE procurement_requests SET status='OVERDUE' WHERE status IN('PENDING DELIVERY','PARTIALLY DELIVERED') AND expected_delivery_date IS NOT NULL AND expected_delivery_date<CURDATE() AND EXISTS(SELECT 1 FROM procurement_request_items x WHERE x.request_id=procurement_requests.id AND x.procurement_status IN('PENDING DELIVERY','PARTIALLY DELIVERED') AND x.quantity_delivered<x.quantity_requested)");
$sql='SELECT r.*,p.ppmp_no,p.reference_budget,d.department_name,COALESCE(SUM(i.quantity_requested),0) ordered,COALESCE(SUM(i.quantity_delivered),0) delivered,COALESCE(SUM(i.quantity_requested-i.quantity_delivered),0) balance,SUM(i.procurement_status="AWAITING QUOTATION") no_bidder_count,SUM(i.procurement_status IN("PENDING DELIVERY","PARTIALLY DELIVERED") AND i.quantity_delivered<i.quantity_requested) pending_count,SUM(i.procurement_status="DELIVERED" OR i.quantity_delivered>=i.quantity_requested) delivered_count,COUNT(*) item_count FROM procurement_requests r JOIN procurement_ppmp p ON p.id=r.ppmp_id LEFT JOIN departments d ON d.id=r.department_id JOIN procurement_request_items i ON i.request_id=r.id GROUP BY r.id';
if($filter==='delivered')$sql.=' HAVING delivered_count>0';elseif($filter==='pending')$sql.=' HAVING pending_count>0';elseif($filter==='no-bidder')$sql.=' HAVING no_bidder_count>0';
$sql.=' ORDER BY r.id DESC';$rows=db_all($sql);
$financialRows=db_all('SELECT request_id,item_description,unit,winning_supplier,procurement_status,quantity_requested,quantity_delivered,unit_cost,quoted_unit_cost FROM procurement_request_items ORDER BY request_id,id');
$financialByRequest=[];
foreach($financialRows as $item){
    $requestId=(int)$item['request_id'];
    if(!isset($financialByRequest[$requestId]))$financialByRequest[$requestId]=['suppliers'=>[],'items'=>[],'no_bidder'=>0.0,'awarded'=>0.0];
    $supplier=trim((string)($item['winning_supplier']??''));$quantity=(int)$item['quantity_requested'];
    $delivered=(int)$item['quantity_delivered'];$deliveryStatus=$delivered>=$quantity?'DELIVERED':($delivered>0?'PARTIAL DELIVERY':'PENDING DELIVERY');
    $financialByRequest[$requestId]['items'][]=$item+['delivery_status'=>$deliveryStatus,'remaining'=>max(0,$quantity-$delivered)];
    if($supplier===''||$item['procurement_status']==='AWAITING QUOTATION'){$financialByRequest[$requestId]['no_bidder']+=$quantity*(float)$item['unit_cost'];continue;}
    if(!isset($financialByRequest[$requestId]['suppliers'][$supplier]))$financialByRequest[$requestId]['suppliers'][$supplier]=['items'=>0,'quantity'=>0,'delivered'=>0,'amount'=>0.0];
    $amount=$quantity*(float)($item['quoted_unit_cost']??0);$financialByRequest[$requestId]['suppliers'][$supplier]['items']++;$financialByRequest[$requestId]['suppliers'][$supplier]['quantity']+=$quantity;$financialByRequest[$requestId]['suppliers'][$supplier]['delivered']+=min($quantity,$delivered);$financialByRequest[$requestId]['suppliers'][$supplier]['amount']+=$amount;$financialByRequest[$requestId]['awarded']+=$amount;
}
procurement_header('Deliveries','deliveries','Track items with no bidder, pending delivery, or completed delivery.');
?>
<div class="metric-row"><div class="metric"><strong><?=count($rows)?></strong><small>Purchase Requests</small></div><div class="metric"><strong><?=array_sum(array_column($rows,'ordered'))?></strong><small>Total Ordered</small></div><div class="metric"><strong><?=array_sum(array_column($rows,'delivered'))?></strong><small>Total Delivered</small></div><div class="metric"><strong><?=array_sum(array_column($rows,'balance'))?></strong><small>Remaining Quantity</small></div></div>
<section class="panel"><div class="panel-head"><div><h2>Delivery Status</h2><small class="muted">View the consolidated supplier award and savings for each PR.</small></div><div class="delivery-tools"><form method="get"><select class="search" name="status" onchange="this.form.submit()"><option value="all" <?=$filter==='all'?'selected':''?>>All Statuses</option><option value="delivered" <?=$filter==='delivered'?'selected':''?>>Delivered</option><option value="pending" <?=$filter==='pending'?'selected':''?>>Pending Deliveries</option><option value="no-bidder" <?=$filter==='no-bidder'?'selected':''?>>No Bidder</option></select></form><a class="btn green" href="../../CSSR_INVENTORY/pages/stock_in.php">Receive Supplies in CSSR</a></div></div><div class="table-wrap"><table class="table"><thead><tr><th>PR No.</th><th>PPMP</th><th>Department</th><th>Expected</th><th>Items</th><th>Ordered</th><th>Delivered</th><th>Remaining</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($rows as $row):$overallStatus=(int)$row['delivered']<=0?'PENDING DELIVERY':((int)$row['balance']<=0?'DELIVERED':'PARTIAL DELIVERY');?><tr><td><strong><?=e($row['procurement_pr_no']?:$row['pr_no'])?></strong></td><td><?=e($row['ppmp_no'])?></td><td><?=e($row['department_name']??'CSSR')?></td><td><?=e($row['expected_delivery_date']??'—')?></td><td><?=$row['item_count']?></td><td><?=$row['ordered']?></td><td><?=$row['delivered']?></td><td><strong><?=$row['balance']?></strong></td><td><span class="badge <?=strtolower(str_replace(' ','-',$overallStatus))?>"><?=e($overallStatus)?></span><small class="ns-next-action">Next: <?=e(nursingWorkflow('purchase',(string)($row['status']??$overallStatus))['next'])?></small></td><td><button class="btn light" type="button" data-view-pr="<?=$row['id']?>">View</button></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="10" class="muted">No delivery records match this filter.</td></tr><?php endif;?></tbody></table></div></section>

<?php foreach($rows as $row):$finance=$financialByRequest[(int)$row['id']]??['suppliers'=>[],'items'=>[],'no_bidder'=>0,'awarded'=>0];$noBidItems=array_values(array_filter($finance['items'],static fn($item)=>trim((string)($item['winning_supplier']??''))===''||$item['procurement_status']==='AWAITING QUOTATION'));$deliveryItems=array_values(array_filter($finance['items'],static fn($item)=>trim((string)($item['winning_supplier']??''))!==''&&$item['procurement_status']!=='AWAITING QUOTATION'));$noBidQuantity=array_sum(array_column($noBidItems,'quantity_requested'));$budget=(float)($row['reference_budget']??0);$consolidated=(float)$finance['awarded']+(float)$finance['no_bidder'];$savings=$budget-$consolidated;?>
<dialog class="pr-financial-dialog" id="prFinancial<?=$row['id']?>">
<header><div><strong>PR Financial Summary</strong><small><?=e($row['procurement_pr_no']?:$row['pr_no'])?> · <?=e($row['ppmp_no'])?></small></div><button class="btn light" type="button" data-close-pr>Close</button></header>
<div class="pr-financial-body">
<h3>Supplier Award Totals</h3><div class="table-wrap"><table class="table supplier-award-table"><thead><tr><th>Winning Supplier</th><th>Items</th><th>Total Quantity</th><th>Total Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php $supplierIndex=0;foreach($finance['suppliers'] as $supplier=>$total):$supplierDialogId='supplierItems'.$row['id'].'_'.$supplierIndex++;$supplierStatus=(int)$total['delivered']<=0?'PENDING DELIVERY':((int)$total['delivered']>=(int)$total['quantity']?'DELIVERED':'PARTIAL DELIVERY');?><tr><td><strong><?=e($supplier)?></strong></td><td><?=$total['items']?></td><td><?=$total['quantity']?></td><td class="amount-cell"><strong><?=number_format((float)$total['amount'],2)?></strong></td><td><span class="badge <?=strtolower(str_replace(' ','-',$supplierStatus))?>"><?=e($supplierStatus)?></span></td><td><button class="btn light" type="button" data-view-supplier="<?=e($supplierDialogId)?>">View</button></td></tr><?php endforeach;?><?php if(!$finance['suppliers']&&!$noBidItems):?><tr><td colspan="6" class="muted">No supplier award records.</td></tr><?php endif;?><?php if($noBidItems):?><tr class="no-bidder-total-row"><td><strong>NO BIDDER</strong></td><td><?=count($noBidItems)?></td><td><?=$noBidQuantity?></td><td class="amount-cell"><strong><?=number_format((float)$finance['no_bidder'],2)?></strong></td><td><span class="badge no-bidder">NO BIDDER</span></td><td><button class="btn light" type="button" data-view-no-bid="noBidItems<?=$row['id']?>">View</button></td></tr><?php endif;?></tbody></table></div>
<div class="pr-financial-totals"><div><span>Supplier Award Total</span><strong><?=number_format((float)$finance['awarded'],2)?></strong></div><div><span>No Bidder Amount</span><strong><?=number_format((float)$finance['no_bidder'],2)?></strong></div><div><span>Consolidated Total Amount</span><strong><?=number_format($consolidated,2)?></strong></div><div><span>PPMP Budget</span><strong><?=number_format($budget,2)?></strong></div><div class="pr-savings <?=$savings<0?'negative':''?>"><span>Savings</span><strong><?=number_format($savings,2)?></strong><small>Budget − Consolidated Total Amount</small></div></div>
</div></dialog>
<?php if($noBidItems):?><dialog class="supplier-items-dialog" id="noBidItems<?=$row['id']?>"><header><div><strong>No Bidder Items</strong><small><?=e($row['procurement_pr_no']?:$row['pr_no'])?></small></div><button class="btn light" type="button" data-close-supplier>Close</button></header><div class="supplier-items-body"><div class="table-wrap"><table class="table"><thead><tr><th>Item Description</th><th>Unit</th><th>Quantity</th><th>Unit Cost</th><th>Total Cost</th></tr></thead><tbody><?php foreach($noBidItems as $item):?><tr><td><strong><?=e($item['item_description'])?></strong></td><td><?=e($item['unit']??'')?></td><td><?=(int)$item['quantity_requested']?></td><td class="amount-cell"><?=number_format((float)$item['unit_cost'],2)?></td><td class="amount-cell"><strong><?=number_format((int)$item['quantity_requested']*(float)$item['unit_cost'],2)?></strong></td></tr><?php endforeach;?></tbody></table></div></div></dialog><?php endif;?>
<?php $supplierIndex=0;foreach($finance['suppliers'] as $supplier=>$total):$supplierDialogId='supplierItems'.$row['id'].'_'.$supplierIndex++;$supplierItems=array_values(array_filter($deliveryItems,static fn($item)=>trim((string)$item['winning_supplier'])===$supplier));?>
<dialog class="supplier-items-dialog" id="<?=e($supplierDialogId)?>"><header><div><strong><?=e($supplier)?></strong><small><?=e($row['procurement_pr_no']?:$row['pr_no'])?> · Awarded Items</small></div><button class="btn light" type="button" data-close-supplier>Close</button></header><div class="supplier-items-body"><div class="table-wrap"><table class="table"><thead><tr><th>Item Description</th><th>Unit</th><th>Ordered</th><th>Delivered</th><th>Remaining</th><th>Unit Cost</th><th>Status</th></tr></thead><tbody><?php foreach($supplierItems as $item):?><tr><td><strong><?=e($item['item_description'])?></strong></td><td><?=e($item['unit']??'')?></td><td><?=(int)$item['quantity_requested']?></td><td><?=(int)$item['quantity_delivered']?></td><td><?=(int)$item['remaining']?></td><td class="amount-cell"><?=number_format((float)($item['quoted_unit_cost']??0),2)?></td><td><span class="badge <?=strtolower(str_replace(' ','-',$item['delivery_status']))?>"><?=e($item['delivery_status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></dialog>
<?php endforeach;?>
<?php endforeach;?>
<style>.delivery-tools,.delivery-badges{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.delivery-tools .search{margin:0;min-width:190px}.delivery-badges .badge{white-space:nowrap}.badge.no-bidder{background:#f1f3f5;color:#57636d}.badge.pending-delivery{background:#fff0cc;color:#8b5d00}.badge.delivered{background:#d9f3e8;color:#087f5b}.amount-cell{text-align:right;font-variant-numeric:tabular-nums}.pr-financial-dialog{width:min(900px,95vw);max-height:90vh;padding:0;border:0;border-radius:13px;overflow:auto;background:#fff;box-shadow:0 25px 80px #102b3b66}.pr-financial-dialog::backdrop{background:#142a397d;backdrop-filter:blur(2px)}.pr-financial-dialog>header{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:14px 17px;border-bottom:1px solid #d8e5ec;background:#f0f7fa}.pr-financial-dialog header strong,.pr-financial-dialog header small{display:block}.pr-financial-dialog header small{margin-top:3px;color:#647b8a}.pr-financial-body{padding:18px}.pr-financial-body h3{margin:0 0 12px}.pr-financial-totals{display:grid;grid-template-columns:repeat(5,minmax(135px,1fr));gap:10px;margin-top:16px}.pr-financial-totals>div{padding:13px;border:1px solid #d6e3ea;border-radius:9px}.pr-financial-totals span,.pr-financial-totals small{display:block;color:#647b8a;font-size:11px}.pr-financial-totals strong{display:block;margin-top:6px;color:#153d54;font-size:18px}.pr-savings{border-left:4px solid #087f5b!important}.pr-savings strong{color:#087f5b!important}.pr-savings.negative{border-left-color:#b42318!important}.pr-savings.negative strong{color:#b42318!important}@media(max-width:800px){.pr-financial-totals{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.pr-financial-totals{grid-template-columns:1fr}}</style>
<style>.supplier-award-table th,.supplier-award-table td,.supplier-items-dialog .table th,.supplier-items-dialog .table td{text-align:center}.supplier-award-table .amount-cell,.supplier-items-dialog .amount-cell{text-align:center}.pr-item-heading,.no-bid-items{margin-top:22px!important}.no-bidder-total-row{background:#f7f8f9}.badge.partial-delivery{background:#e8f1fb;color:#245f91}.no-bid-items[hidden]{display:none}.no-bid-items h3{margin-bottom:12px}.supplier-items-dialog{width:min(900px,95vw);max-height:86vh;padding:0;border:0;border-radius:12px;overflow:auto;background:#fff;box-shadow:0 25px 80px #102b3b66}.supplier-items-dialog::backdrop{background:#142a397d}.supplier-items-dialog>header{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:14px 17px;border-bottom:1px solid #d8e5ec;background:#f0f7fa}.supplier-items-dialog header strong,.supplier-items-dialog header small{display:block}.supplier-items-dialog header small{margin-top:3px;color:#647b8a}.supplier-items-body{padding:18px}</style>
<script>document.querySelectorAll('[data-view-pr]').forEach(button=>button.onclick=()=>document.getElementById('prFinancial'+button.dataset.viewPr).showModal());document.querySelectorAll('[data-view-supplier]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.viewSupplier)?.showModal());document.querySelectorAll('[data-view-no-bid]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.viewNoBid)?.showModal());document.querySelectorAll('.supplier-items-dialog').forEach(dialog=>{dialog.querySelector('[data-close-supplier]').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})});document.querySelectorAll('.pr-financial-dialog').forEach(dialog=>{dialog.querySelector('[data-close-pr]').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})});</script>
